class Solution:
    def findMinFibonacciNumbers(self, k: int) -> int:
        fibs = [1, 1]
        while fibs[-1] < k:
            fibs.append(fibs[-1] + fibs[-2])
        INF = float('inf')
        dp = [0] + [INF] * k
        for x in range(1, k + 1):
            for f in fibs:
                if f > x:
                    break
                if dp[x - f] + 1 < dp[x]:
                    dp[x] = dp[x - f] + 1
        return dp[k]

