class Solution {
public:
    int findMinFibonacciNumbers(int k) {
        vector<long long> fibs{1, 1};
        while (fibs.back() < k) fibs.push_back(fibs[fibs.size()-1] + fibs[fibs.size()-2]);
        const long long INF = LLONG_MAX / 2;
        vector<long long> dp(k + 1, INF);
        dp[0] = 0;
        for (int x = 1; x <= k; ++x)
            for (long long f : fibs)
                if (f <= x && dp[x - f] + 1 < dp[x]) dp[x] = dp[x - f] + 1;
        return (int)dp[k];
    }
};

