    int findMinFibonacciNumbers(int k) {
        int ans = 0;
        while (k > 0) {
            long long a = 1, b = 1;
            while (b <= k) { long long t = a + b; a = b; b = t; }
            k -= (int)a;
            ++ans;
        }
        return ans;
    }
};

